    "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface AdReferral {
  adReferralId: number;
  companyId: number;
  channelId: number;
  customerPhone: string;
  clientId: number | null;
  isNewCustomer: boolean;
  waMessageId: string;
  source: string;
  sourceType: string | null;
  sourceId: string | null;
  sourceUrl: string | null;
  headline: string | null;
  body: string | null;
  mediaType: string | null;
  referredAt: string;
}

export interface AdPerformanceAd {
  sourceId: string | null;
  headline: string | null;
  sourceUrl: string | null;
  customers: number;
  newCustomers: number;
  booked: number;
  bought: number;
  salesAfterChat: number;
  firstAt: string;
  lastAt: string;
}

export interface AdPerformanceTotals {
  customers: number;
  newCustomers: number;
  booked: number;
  bought: number;
  salesAfterChat: number;
}

export interface AdReferralPerformanceResponse {
  period: {
    startDate: string;
    endDate: string;
  };
  attributionDays: number;
  totals: AdPerformanceTotals;
  ads: AdPerformanceAd[];
  dataSince: string | null;
}

export interface GetAllAdReferralsRequest {
  companyId: number;
  startDate?: string;
  endDate?: string;
  sourceId?: string;
  onlyNew?: boolean;
}

export interface GetAdReferralPerformanceRequest {
  companyId: number;
  startDate?: string;
  endDate?: string;
  attributionDays?: number;
}

export interface AdReferralListResponse {
  adReferrals: AdReferral[];
}

export async function getAllAdReferrals(payload: GetAllAdReferralsRequest): Promise<AdReferral[]> {
  const res = await fetch(BASE_URL + "/all_adReferrals", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "adReferrals": [{ ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: AdReferralListResponse = await res.json();
  return data.adReferrals ?? [];
}

export async function getAdReferralPerformance(payload: GetAdReferralPerformanceRequest): Promise<AdReferralPerformanceResponse> {
  const res = await fetch(BASE_URL + "/adReferrals/performance", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "adReferralPerformance": [{ ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data = await res.json();
  if (data.result && data.result.length > 0) {
    return data.result[0];
  } else {
    // Return a default structure if no data, to avoid errors downstream
    return {
      period: { startDate: payload.startDate || '', endDate: payload.endDate || '' },
      attributionDays: payload.attributionDays || 14,
      totals: { customers: 0, newCustomers: 0, booked: 0, bought: 0, salesAfterChat: 0 },
      ads: [],
      dataSince: null,
    };
  }
}
