    "content": "import { useCallback, useEffect, useState } from 'react';
import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged } from '../../../utils/refreshBus';
import {
  getAdReferralPerformance,
  AdReferralPerformanceResponse,
  GetAdReferralPerformanceRequest,
} from '../../../api/adReferralApi';

export const useAdReferral = (startDate: string, endDate: string) => {
  const { companyId } = useUser();
  const { showToast, toastProps } = useToast();
  const [performanceData, setPerformanceData] = useState<AdReferralPerformanceResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadPerformance = useCallback(async () => {
    if (!companyId) return;
    setLoading(true);
    setError(null);
    try {
      const payload: GetAdReferralPerformanceRequest = { companyId, startDate, endDate };
      const data = await getAdReferralPerformance(payload);
      setPerformanceData(data);
    } catch (err) {
      const errorMessage = (err as Error).message ?? 'Error desconocido al cargar el rendimiento de anuncios.';
      showToast(errorMessage, 'danger');
      setError(errorMessage);
      setPerformanceData(null);
    } finally {
      setLoading(false);
    }
  }, [companyId, startDate, endDate, showToast]);

  useEffect(() => {
    loadPerformance();
  }, [loadPerformance]);

  useIonViewWillEnter(() => {
    loadPerformance();
  });

  useEffect(() => onDataChanged(() => loadPerformance()), [loadPerformance]);

  return {
    performanceData,
    loading,
    error,
    toastProps,
  };
};

export type AdReferralVM = ReturnType<typeof useAdReferral>;
